import{_ as s,a0 as r,w as l,s as a,ao as u,I as p,x as t,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 下执行 bin 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 下执行 bin 文件 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 下执行 bin 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 下执行 bin 文件 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/How To Execute bin Files In Linux","title":"如何在 Linux 下执行 bin 文件","tag":"201403","desc":""},"relativePath":"201403/How To Execute bin Files In Linux.md","filePath":"[post].md"}'),x={name:"201403/How To Execute bin Files In Linux.md"};function d(m,n,g,b,T,f){const e=r("Link");return l(),a("div",null,[n[11]||(n[11]=u(`<h1 id="如何在-linux-下执行-bin-文件" tabindex="-1">如何在 Linux 下执行 bin 文件 <a class="header-anchor" href="#如何在-linux-下执行-bin-文件" aria-label="Permalink to “如何在 Linux 下执行 bin 文件”">​</a></h1><p>嗨，各位 <strong>Linux</strong> 极客们，</p><p>在这篇简短教程中，我会指导你们如何在你的 Linux 机器上安装 <strong>.bin</strong> 文件。并不是一些可怕的终端命令，我保证！但是我同样会展示如何在终端上操作 。</p><p>###什么是 .bin 文件？</p><p>.bin 文件是在 Linux 和类 Unix 操作系统上的自执行文件。在执行 .bin 文件之前，你需要给它执行权限。这可以通过命令行或者 gui 完成。如果你喜欢用命令行那么打开一个新的终端并运行如下的命令来给予文件执行权限。</p><pre><code>chmod +x filename.bin
</code></pre><p>接着用下面的命令执行。</p><pre><code>./filename.bin
</code></pre><p>确保你在运行上面的命令的时候是超级用户。</p><p>那又如何从 gui 来完成呢？进入 .bin 文件的目录并点击鼠标右键，接着如下图所示进入属性。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/exec1.png" alt=""></p><p>选择 <strong>Permissions</strong> 并勾选 <strong>Allow executing file as a program</strong> 。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/exec2.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/exec3.png" alt=""></p><p>双击文件后它就会执行。这样就完成了。</p><hr>`,16)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),i(e,{href:"http://www.unixmen.com/execute-bin-files-linux/"},{default:o(()=>[...n[0]||(n[0]=[t("http://www.unixmen.com/execute-bin-files-linux/",-1)])]),_:1})]),p("p",null,[n[4]||(n[4]=t("译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校对：",-1)),i(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[3]||(n[3]=[t("Caroline",-1)])]),_:1})]),p("p",null,[n[8]||(n[8]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...n[7]||(n[7]=[t("Linux中国",-1)])]),_:1}),n[10]||(n[10]=t(" 荣誉推出",-1))])])}const c=s(x,[["render",d]]);export{C as __pageData,c as default};
